#include <cstddef>
#include <cstdint>
#include <cmath>
extern "C" double lamberts_ellipsoidal_distance(const std::int64_t*v,std::size_t n){constexpr double pi=3.14159265358979323846264338327950288,inv=-1.0e300;if(n!=4)return inv;if(v[0]<-90000000||v[0]>90000000||v[2]<-90000000||v[2]>90000000||v[1]<-180000000||v[1]>180000000||v[3]<-180000000||v[3]>180000000)return inv;if(v[0]==v[2]&&v[1]==v[3])return inv;double lat1=v[0]/1e6,lon1=v[1]/1e6,lat2=v[2]/1e6,lon2=v[3]/1e6,p1=lat1*pi/180,p2=lat2*pi/180,l1=lon1*pi/180,l2=lon2*pi/180;double h=std::sqrt(std::pow(std::sin((p2-p1)/2),2)+std::cos(p1)*std::cos(p2)*std::pow(std::sin((l2-l1)/2),2));if(h==0)return inv;double sigma=2*std::asin(h),f=(6378137.0-6356752.314245)/6378137.0,b1=std::atan((1-f)*std::tan(lat1*pi/180)),b2=std::atan((1-f)*std::tan(lat2*pi/180)),p=(b1+b2)/2,q=(b2-b1)/2;double x=(sigma-std::sin(sigma))*((std::pow(std::sin(p),2)*std::pow(std::cos(q),2))/std::pow(std::cos(sigma/2),2));double y=(sigma+std::sin(sigma))*((std::pow(std::cos(p),2)*std::pow(std::sin(q),2))/std::pow(std::sin(sigma/2),2));return 6378137.0*(sigma-(f/2)*(x+y));}
